import{_ as a,o as n,c as t,a3 as l}from"./chunks/framework.MGD2uYU7.js";const g=JSON.parse('{"title":"SC-43 — Quản lý dự án NOXH (Admin)","description":"","frontmatter":{"title":"SC-43 — Quản lý dự án NOXH (Admin)"},"headers":[],"relativePath":"wireframes/admin/sc-43-quan-ly-du-an.md","filePath":"wireframes/admin/sc-43-quan-ly-du-an.md","lastUpdated":1791606799000}'),i={name:"wireframes/admin/sc-43-quan-ly-du-an.md"};function d(c,s,p,e,r,o){return n(),t("div",null,[...s[0]||(s[0]=[l('<h1 id="sc-43-—-quan-ly-du-an-noxh" tabindex="-1">SC-43 — Quản lý dự án NOXH <a class="header-anchor" href="#sc-43-—-quan-ly-du-an-noxh" aria-label="Permalink to &quot;SC-43 — Quản lý dự án NOXH&quot;">​</a></h1><p><span class="wf-badge info">ADMIN</span> <span class="wf-badge danger">TRẦN/m² — BR-HS-06</span> <span class="wf-badge info">Route: /admin/du-an</span> <span class="wf-badge muted">Nguồn: docs/05 §3 SC-40..49 · docs/02 FR-ADM-04/FR-ADM-05 · docs/06 §4.10 endpoints 51 + 11 · docs/07 §2.4 · docs/08 BR-HS-06 / BR-ADM-01/02</span></p><p><strong>Ai xem màn này</strong>: Quản trị viên (guard ADMIN 🛡 — USER gọi endpoints 51 → 403, guest → 401). Đây là màn CRUD danh mục dự án NOXH — đầu vào của tin đăng (SC-42), trang mua nhà (SC-02/04) và đấu giá. <strong>Mục đích</strong>: tạo/sửa/xóa dự án với đủ ràng buộc contract docs/06 §4.10; trong đó <strong>trần bán lại/m² (<code>resalePriceCapM2</code>) là trường load-bearing của BR-HS-06</strong> — con số admin nhập ở đây chính là ngưỡng chặn tin vượt giá trên TOÀN sàn. Mỗi mutation = toast + audit log. <strong>Ví dụ số dùng trong bản vẽ</strong>: &quot;bây giờ&quot; 10/10/2026 14:31 (GMT+7) · admin.minh đang đăng nhập · danh mục 3 dự án: <code>HP-380</code> (Hải Phòng, trần 30.000.000 ₫/m² — đúng dự án của tin vượt trần SC-42), <code>BN-220</code> (Bắc Ninh, trần 25.000.000 ₫/m²), <code>HN-105</code> (Hà Nội, trần 33.000.000 ₫/m²).</p><h2 id="_1-desktop-—-bang-du-an-crud" tabindex="-1">1. Desktop — bảng dự án (CRUD) <a class="header-anchor" href="#_1-desktop-—-bang-du-an-crud" aria-label="Permalink to &quot;1. Desktop — bảng dự án (CRUD)&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/admin/du-an?page=1</span></div><div class="wf-body"><div class="wf-row" style="gap:0;align-items:stretch;"><div class="wf-admin-rail" style="border-radius:0;"><span class="brand">AnPhuc Admin</span><span class="item">Dashboard</span><span class="item">KYC</span><span class="item">Tin</span><span class="item active">Dự án</span><span class="item">Đấu giá</span><span class="item">Thanh toán</span><span class="item">Người dùng</span><span class="item">Audit</span><span class="item" style="margin-top:auto;color:#9ca3af;">← Về trang người dùng</span></div><div class="wf-grow wf-col" style="padding:16px;gap:12px;"><div class="wf-row between middle"><div class="wf-col" style="gap:2px;"><span class="wf-title xl">Quản lý dự án NOXH</span><span class="wf-small">3 dự án · cột &quot;Trần bán lại/m²&quot; là ngưỡng BR-HS-06 áp lên mọi tin của dự án <span class="wf-callout">2</span></span></div><div class="wf-row middle" style="gap:8px;"><span class="wf-btn sm ghost">⭳ Export CSV</span><span class="wf-btn primary">＋ Tạo dự án</span><span class="wf-avatar">M</span></div></div><div class="wf-row middle" style="gap:8px;"><div class="wf-search" style="flex:1;max-width:340px;"><span>🔎</span><span>Tìm tên / mã dự án / địa chỉ…</span></div><div class="wf-input" style="max-width:180px;"><span class="wf-small wf-muted">Tỉnh/TP: Tất cả</span><span>▾</span></div><div class="wf-input" style="max-width:200px;"><span class="wf-small wf-muted">Tiến độ: Tất cả</span><span>▾</span></div><div class="wf-input" style="max-width:200px;"><span class="wf-small wf-muted">Pháp lý: Tất cả</span><span>▾</span></div></div><table class="wf-table"><thead><tr><th>Dự án</th><th>Địa chỉ</th><th>Giá dự kiến/m²</th><th>Trần bán lại/m² <span class="wf-callout">2</span></th><th>Tổng căn</th><th>Tiến độ <span class="wf-callout">3</span></th><th>Pháp lý <span class="wf-callout">3</span></th><th>Cập nhật <span class="wf-callout">4</span></th><th></th></tr></thead><tbody><tr><td><b>NOXH Nhà ở xã hội HP-380</b><br><span class="wf-small">prj_01J9A2K8M2 · APARTMENT</span></td><td><span class="wf-small">380 Võ Nguyên Giáp<br>Vĩnh Niệm · Lê Chân · Hải Phòng</span></td><td>22.000.000 ₫</td><td><b class="wf-strong">30.000.000 ₫</b></td><td>480 · 2 loại căn</td><td><span class="wf-badge warn">CONSTRUCTING</span></td><td><span class="wf-badge ok">SALES_ELIGIBLE</span></td><td><span class="wf-small">08/10/2026 15:40<br>admin.minh</span></td><td><span class="wf-row" style="gap:4px;"><span class="wf-btn sm">Sửa</span><span class="wf-btn sm ghost wf-danger-text">Xóa</span></span></td></tr><tr><td><b>NOXH BN-220 Bắc Ninh</b><br><span class="wf-small">prj_01J9B7R3T9 · APARTMENT</span></td><td><span class="wf-small">Đường Lý Thái Tổ<br>Võ Cường · TP Bắc Ninh · Bắc Ninh</span></td><td>18.000.000 ₫</td><td><b class="wf-strong">25.000.000 ₫</b></td><td>320 · 3 loại căn</td><td><span class="wf-badge warn">FINISHING</span></td><td><span class="wf-badge ok">PINK_BOOK_ISSUED</span></td><td><span class="wf-small">05/10/2026 09:12<br>admin.minh</span></td><td><span class="wf-row" style="gap:4px;"><span class="wf-btn sm">Sửa</span><span class="wf-btn sm ghost wf-danger-text">Xóa</span></span></td></tr><tr><td><b>NOXH HN-105 Hà Nội</b><br><span class="wf-small">prj_01J9C4W8E5 · APARTMENT</span></td><td><span class="wf-small">105 Nguyễn Trãi<br>Thượng Đình · Thanh Xuân · Hà Nội</span></td><td>25.000.000 ₫</td><td><b class="wf-strong">33.000.000 ₫</b></td><td>640 · 5 loại căn</td><td><span class="wf-badge warn">CONSTRUCTING</span></td><td><span class="wf-badge info">CONSTRUCTION_PERMIT</span></td><td><span class="wf-small">01/10/2026 11:30<br>admin.lan</span></td><td><span class="wf-row" style="gap:4px;"><span class="wf-btn sm">Sửa</span><span class="wf-btn sm ghost wf-danger-text">Xóa</span></span></td></tr></tbody></table><div class="wf-row between middle"><span class="wf-small">20 dòng/trang · đọc qua `GET /projects` — `limit` tối đa 50 (vượt → 400 VALIDATION_ERROR) <span class="wf-callout">1</span></span><div class="wf-pagination" style="margin-top:0;"><span class="pg">‹</span><span class="pg active">1</span><span class="pg">›</span></div></div></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích bảng (trace: docs/05 §3 SC-40..49 · docs/06 §4.10 · docs/08 BR-HS-06/BR-ADM)</div><ol><li><span class="num">1</span><span><b>DataTable server-side</b>: đọc `GET /projects` (endpoint 11 — cùng nguồn công khai SC-02/04, `limit` ≤ 50); mutation qua endpoints 51 `POST/PATCH/DELETE /admin/projects` (ADMIN 🛡). Filter/sort/page sync vào URL (shareable như mọi màn admin — docs/05 §3). Export CSV theo chuẩn FR-STAT-02. <span class="ref">FR-ADM-04</span> <span class="ref">docs/06 §4.10</span></span></li><li><span class="num">2</span><span><b>Cột &quot;Trần bán lại/m²&quot; in đậm có chủ đích</b>: giá trị `resale_price_cap_m2` là ngưỡng của BR-HS-06 — tin có `floor(price/area)` vượt số này bị chặn ngay lúc submit (422 `PRICE_ABOVE_CAP`, message nguyên văn &quot;Giá vượt trần {cap} ₫/m² của dự án theo quy định&quot;) VÀ bị chặn lúc admin approve ở SC-42. Sửa một con số ở đây = đổi luật giá cho mọi tin của dự án → phải qua confirm có reason (mục 2–3). <span class="ref">BR-HS-06</span> <span class="ref">docs/06 §5</span></span></li><li><span class="num">3</span><span><b>Tiến độ + Pháp lý là HAI enum độc lập</b> (docs/07 §2.4), không gộp một badge. Tiến độ: PLANNING · PREPARING · CONSTRUCTING (default) · FINISHING · HANDOVER · COMPLETED · SUSPENDED. Pháp lý: IN_PROGRESS (default) · LAND_DECISION · CONSTRUCTION_PERMIT · SALES_ELIGIBLE · PINK_BOOK_ISSUED · DISPUTED. `DISPUTED`/`SUSPENDED` → badge danger. FE map nhãn tiếng Việt cố định, không tự sinh giá trị enum. <span class="ref">docs/05 §6 StatusBadge</span></span></li><li><span class="num">4</span><span><b>Cột &quot;Cập nhật&quot;</b> = `updatedAt` + admin thực hiện (lấy từ audit trail, không có trường createdBy trong payload — docs/06 §4.10). Click mở SC-49 Audit lọc `PROJECT_CREATE/UPDATE/DELETE` của đúng dự án. <span class="ref">BR-ADM-01</span> <span class="ref">BR-ADM-02</span></span></li></ol></div><h2 id="_2-form-tao-sua-du-an-—-truong-gia-tran-m2-la-load-bearing" tabindex="-1">2. Form tạo / sửa dự án — trường giá trần/m² là load-bearing <a class="header-anchor" href="#_2-form-tao-sua-du-an-—-truong-gia-tran-m2-la-load-bearing" aria-label="Permalink to &quot;2. Form tạo / sửa dự án — trường giá trần/m² là load-bearing&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:760px;gap:10px;"><span class="wf-state-label">FORM TẠO MỚI — POST /admin/projects → 201</span><div class="wf-card"><div class="pad wf-col" style="gap:10px;"><div class="wf-row between middle"><span class="wf-title lg">Tạo dự án NOXH</span><span class="wf-badge info">＊ = bắt buộc</span></div><div class="wf-card flat"><div class="pad wf-col" style="gap:8px;"><span class="wf-strong">Thông tin cơ bản</span><div class="wf-col" style="gap:4px;"><span class="wf-small">Tên dự án ＊ (2–200 ký tự)</span><div class="wf-input filled"><span>NOXH Nhà ở xã hội HP-380</span><span class="caret">✎</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small">Địa chỉ ＊ (5–300 ký tự)</span><div class="wf-input filled"><span>380 Võ Nguyên Giáp</span><span class="caret">✎</span></div></div><div class="wf-grid cols-3" style="gap:8px;"><div class="wf-col" style="gap:4px;"><span class="wf-small">Phường/Xã ＊ (1–100)</span><div class="wf-input filled"><span>Vĩnh Niệm</span><span class="caret">✎</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small">Quận/Huyện ＊ (1–100)</span><div class="wf-input filled"><span>Lê Chân</span><span class="caret">✎</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small">Tỉnh/TP ＊ (1–100)</span><div class="wf-input filled"><span>Hải Phòng</span><span class="caret">✎</span></div></div></div><div class="wf-row middle wrap" style="gap:16px;"><span class="wf-small">Loại hình ＊:</span><span class="wf-row middle" style="gap:6px;"><span class="wf-radio checked"></span><span class="wf-small">APARTMENT (default)</span></span><span class="wf-row middle" style="gap:6px;"><span class="wf-radio"></span><span class="wf-small">TOWNHOUSE</span></span></div><div class="wf-col" style="gap:4px;"><span class="wf-small">Chủ đầu tư (tùy chọn, 1–200 ký tự)</span><div class="wf-input filled"><span>Công ty CP Phát triển nhà HP</span><span class="caret">✎</span></div></div></div></div><div class="wf-card flat"><div class="pad wf-col" style="gap:8px;"><span class="wf-strong">Giá &amp; quy mô</span><div class="wf-grid cols-2" style="gap:8px;"><div class="wf-col" style="gap:4px;"><span class="wf-small">Giá dự kiến/m² ＊ (số nguyên ≥ 1, ₫)</span><div class="wf-input filled"><span>22.000.000</span><span class="caret">✎</span></div><span class="wf-small wf-muted">Thông tin tham khảo hiển thị SC-04 — không dùng để chặn tin.</span></div><div class="wf-col" style="gap:4px;border:2px solid var(--wf-danger);border-radius:6px;padding:8px;background:var(--wf-danger-soft);"><span class="wf-small wf-strong wf-danger-text">Trần bán lại/m² ＊ (số nguyên ≥ 1, ₫) — LOAD-BEARING <span class="wf-callout danger">5</span></span><div class="wf-input filled" style="border-color:var(--wf-danger);"><span class="wf-strong">30.000.000</span><span class="caret">✎</span></div><span class="wf-small">Ngưỡng BR-HS-06: tin vượt số này → 422 lúc submit + chặn APPROVE ở SC-42.</span></div></div><div class="wf-grid cols-2" style="gap:8px;"><div class="wf-col" style="gap:4px;"><span class="wf-small">Tổng số căn ＊ (1–100.000)</span><div class="wf-input filled"><span>480</span><span class="caret">✎</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small">Số tầng ＊ (1–150)</span><div class="wf-input filled"><span>21</span><span class="caret">✎</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small">Mật độ xây dựng % ＊ (0–100)</span><div class="wf-input filled"><span>38</span><span class="caret">✎</span></div></div><div class="wf-row" style="gap:8px;"><div class="wf-col wf-grow" style="gap:4px;"><span class="wf-small">Khởi công ＊ (1900–2100)</span><div class="wf-input filled"><span>2024</span><span class="caret">✎</span></div></div><div class="wf-col wf-grow" style="gap:4px;"><span class="wf-small">Bàn giao ＊ (1900–2100)</span><div class="wf-input filled"><span>2027</span><span class="caret">✎</span></div></div></div></div></div></div><div class="wf-card flat"><div class="pad wf-col" style="gap:8px;"><div class="wf-row between middle"><span class="wf-strong">Loại căn hộ (tối đa 30 dòng)</span><span class="wf-btn sm ghost">＋ Thêm loại căn</span></div><table class="wf-table"><thead><tr><th>Tên loại căn (1–60)</th><th>Diện tích m² (15–500)</th><th>Số căn (0–100.000)</th><th></th></tr></thead><tbody><tr><td>2 phòng ngủ tiêu chuẩn</td><td>69,5</td><td>120</td><td><span class="wf-btn sm ghost wf-danger-text">✕</span></td></tr><tr><td>2 PN căn góc</td><td>72</td><td>96</td><td><span class="wf-btn sm ghost wf-danger-text">✕</span></td></tr></tbody></table><span class="wf-small wf-muted">Diện tích loại căn khớp dữ liệu tin thật (CT2-A17.09 = 69,5 m², CT1-B09.03 = 72 m² — SC-42).</span><span class="wf-strong">Tiện ích (tối đa 50 mục, mỗi mục 1–200 ký tự)</span><div class="wf-row wrap" style="gap:6px;"><span class="wf-btn sm ghost">Công viên nội khu ✕</span><span class="wf-btn sm ghost">Nhà trẻ ✕</span><span class="wf-btn sm ghost">Bãi đỗ xe nổi ✕</span><span class="wf-btn sm ghost">＋ Thêm tiện ích</span></div></div></div><div class="wf-card flat"><div class="pad wf-col" style="gap:8px;"><span class="wf-strong">Trạng thái &amp; mô tả</span><div class="wf-grid cols-2" style="gap:8px;"><div class="wf-col" style="gap:4px;"><span class="wf-small">Tiến độ ＊ (enum docs/07 §2.4)</span><div class="wf-input"><span>CONSTRUCTING — Đang xây dựng (default)</span><span>▾</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small">Pháp lý ＊ (enum docs/07 §2.4)</span><div class="wf-input"><span>SALES_ELIGIBLE — Đủ điều kiện bán</span><span>▾</span></div></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small">Mô tả (tối đa 5.000 ký tự)</span><div class="wf-input filled" style="min-height:64px;align-items:flex-start;"><span class="wf-small">Dự án nhà ở xã hội 21 tầng, 480 căn hộ tại Vĩnh Niệm, Lê Chân — tiếp nhận hồ sơ mua/thuê mua theo nghị định NOXH…</span><span class="caret">✎</span></div><div class="wf-row between"><span class="wf-small wf-muted">Hiển thị nguyên văn ở SC-04 (không rich-text v1)</span><span class="wf-small">142/5.000</span></div></div></div></div><div class="wf-note">Payload KHÔNG BAO GIỜ chứa `createdBy` — server lấy người tạo từ token, dấu vết nằm ở audit `PROJECT_CREATE` (docs/06 §4.10 · BR-ADM-01). Không có trường ảnh dự án / GPS / milestone % / lịch thanh toán trong contract — wireframe không vẽ, designer không thêm. <span class="wf-callout">7</span></div><div class="wf-row" style="margin-top:2px;"><span class="wf-btn ghost" style="flex:1;">Hủy</span><span class="wf-btn primary" style="flex:2;">TẠO DỰ ÁN</span></div><div class="wf-note">Chế độ SỬA (`PATCH /admin/projects/{id}` — partial): chỉ gửi trường thay đổi; nút Save <b>disabled khi form chưa sửa gì</b> (dirty-check từng trường) vì no-op PATCH vẫn trả 200 nhưng KHÔNG ghi audit (BR-ADM-01 — tránh log nhiễu). Sửa `resalePriceCapM2` → confirm riêng có reason như mục 3. <span class="wf-callout">6</span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích form (trace: docs/06 §4.10 · docs/08 BR-HS-06/BR-ADM-01)</div><ol><li><span class="num">5</span><span><b>Trần bán lại/m² — trường load-bearing của BR-HS-06</b>: nguồn số liệu là văn bản Sở Xây dựng (OQ-4), <b>cấm nhập ước lượng</b>; hint tại chỗ nhắc admin con số này chặn tin trên toàn sàn (submit 422 `PRICE_ABOVE_CAP` + re-validate lúc approve — SC-42 callout 5). FE validate int ≥ 1 trước khi gửi; đổi giá trị trên dự án ĐANG có tin IN_REVIEW → warn &quot;các tin chờ duyệt sẽ bị re-validate theo trần mới&quot;. <span class="ref">BR-HS-06</span> <span class="ref">docs/06 §5</span></span></li><li><span class="num">6</span><span><b>Tạo/sửa đều = toast + audit</b>: `POST` 201 → audit `PROJECT_CREATE` diff `{after}`; `PATCH` 200 partial → audit `PROJECT_UPDATE` diff `{before, after}` chỉ của trường đổi; no-op → không audit (FE chặn bằng Save-disabled). Log audit append-only, không sửa xóa được. <span class="ref">BR-ADM-01</span> <span class="ref">BR-ADM-02</span></span></li><li><span class="num">7</span><span><b>Đúng ranh contract docs/06 §4.10</b>: đủ các nhóm trường name/address/ward/district/province/propertyType/developer/expectedPriceM2/resalePriceCapM2/totalUnits/unitTypes/amenities/constructionDensityPercent/floors/startYear/completionYear/status/legalStatus/description — không thêm field ngoài spec (muốn thêm → PM sửa docs/06 trước). Unique `(name, address)` → trùng sẽ 409 (mục 4). <span class="ref">docs/06 §4.10</span> <span class="ref">FR-ADM-04</span></span></li></ol></div><h2 id="_3-delete-confirm-—-hard-delete-audit-la-dau-vet-duy-nhat" tabindex="-1">3. Delete-confirm — hard delete, audit là dấu vết duy nhất <a class="header-anchor" href="#_3-delete-confirm-—-hard-delete-audit-la-dau-vet-duy-nhat" aria-label="Permalink to &quot;3. Delete-confirm — hard delete, audit là dấu vết duy nhất&quot;">​</a></h2><div class="wf"><div class="wf-modal-overlay"><div class="wf-modal"><div class="head" style="color:var(--wf-danger);">Xóa dự án NOXH BN-220 Bắc Ninh?</div><div class="wf-lines" style="margin:10px 0;"><div class="wf-row between"><span class="wf-text">Tin đang tham chiếu</span><span class="wf-warn-text">1 tin (CT5-D02.11 · IN_REVIEW) <span class="wf-callout danger">8</span></span></div></div><div class="wf-note" style="background:var(--wf-danger-soft);border-color:var(--wf-danger);color:var(--wf-danger);"><b>HARD DELETE — không soft-delete, không khôi phục.</b> Bản ghi mất khỏi `GET /projects`; dấu vết duy nhất là audit `PROJECT_DELETE` diff `{before}` (full snapshot, append-only — BR-ADM-02). Cặp (name, address) được giải phóng → tạo lại được.</div><div class="wf-col" style="gap:4px;margin-top:8px;"><span class="wf-small wf-strong">Lý do xóa ＊ (10–500 ký tự — quy trình Ops)</span><div class="wf-input filled" style="min-height:52px;align-items:flex-start;"><span class="wf-small">Tạo trùng lặp với hồ sơ BN-220 cũ — dọn danh mục theo ticket OPS-112, đã đối chiếu không có tin LISTED.</span><span class="caret">✎</span></div></div><div class="wf-col" style="gap:4px;margin-top:6px;"><span class="wf-small">Nhập đúng mã dự án để mở khóa nút xóa (chốt chặn FE chống click nhầm):</span><div class="wf-input filled"><span class="wf-strong">BN-220</span><span class="caret">✎</span></div></div><div class="wf-row" style="margin-top:12px;"><span class="wf-btn" style="flex:1;">Hủy</span><span class="wf-btn danger" style="flex:1;">XÓA VĨNH VIỄN <span class="wf-callout">9</span></span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích delete (trace: docs/06 endpoint 51 · docs/08 BR-ADM)</div><ol><li><span class="num">8</span><span><b>Gap cần PM duyệt</b>: docs/08 chưa quy định có CHẶN xóa dự án khi còn tin tham chiếu hay không. Wireframe tạm vẽ phương án <b>cảnh báo cứng</b> — hiện rõ số tin đang tham chiếu + reason bắt buộc nêu cách xử lý (như ví dụ BN-220 còn 1 tin IN_REVIEW); phương án chặt hơn là <b>chặn</b> xóa khi còn tin `LISTED/IN_REVIEW/RESERVED`. PM chốt trên docs/08 trước khi dev. <span class="ref">docs/08</span> <span class="ref">FR-ADM-04</span></span></li><li><span class="num">9</span><span><b>Nút xóa enable khi đủ HAI điều kiện FE</b>: reason ≥ 10 ký tự + gõ đúng mã dự án (type-to-confirm). Lưu ý contract: `DELETE /admin/projects/{id}` hiện KHÔNG nhận `reason` — quy trình Ops bắt buộc có; cần PM bổ sung trường vào docs/06 endpoint 51 (tương tự ghi chú duyệt ở SC-41). Thành công → toast + audit `PROJECT_DELETE` `{before}`; đang gửi → cả hai nút loading disabled (chống double-submit). <span class="ref">BR-ADM-01</span> <span class="ref">docs/05 §1.3</span></span></li></ol></div><h2 id="_4-toast-ket-qua-loi-copy-nguyen-van-docs-06-§5" tabindex="-1">4. Toast kết quả &amp; lỗi (copy nguyên văn docs/06 §5) <a class="header-anchor" href="#_4-toast-ket-qua-loi-copy-nguyen-van-docs-06-§5" aria-label="Permalink to &quot;4. Toast kết quả &amp; lỗi (copy nguyên văn docs/06 §5)&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:640px;gap:4px;"><span class="wf-state-label">TẠO THÀNH CÔNG — POST 201</span><div class="wf-toast ok"><b>Đã tạo dự án NOXH HN-105 Hà Nội</b> — audit PROJECT_CREATE đã ghi · quay về danh sách</div><span class="wf-state-label" style="margin-top:10px;">CẬP NHẬT THÀNH CÔNG — PATCH 200 (partial)</span><div class="wf-toast ok"><b>Đã cập nhật HP-380</b> — 2 trường thay đổi (resalePriceCapM2, status) · audit PROJECT_UPDATE lưu diff before/after</div><span class="wf-state-label" style="margin-top:10px;">409 — TRÙNG (name, address) UNIQUE</span><div class="wf-toast danger">Dự án với tên và địa chỉ này đã tồn tại</div><span class="wf-small">Message nguyên văn `CONFLICT` (docs/06 §5). Form giữ nguyên dữ liệu, field-error highlight đồng thời ô Tên + Địa chỉ + link &quot;Mở dự án trùng&quot; — không reset form.</span><span class="wf-state-label" style="margin-top:10px;">400 — VALIDATION_ERROR (errors[] theo từng field)</span><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><div class="wf-col" style="gap:2px;"><span class="wf-small">Giá dự kiến/m² ＊</span><div class="wf-input error"><span>0</span></div><span class="wf-field-error">Giá trị phải là số nguyên ≥ 1</span></div><span class="wf-small wf-muted">Server trả `errors[]` kèm path — FE map đúng ô lỗi (component chuẩn docs/05 §6), scroll tới lỗi đầu tiên, không chặn các nhóm trường khác.</span></div></div><span class="wf-state-label" style="margin-top:10px;">404 — MỞ SỬA TỪ LIST STALE</span><div class="wf-toast danger">Không tìm thấy dự án</div><span class="wf-small">Nguyên văn `HOUSING_NOT_FOUND` (docs/06 §5) — xảy ra khi admin A mở form Sửa của dự án mà admin B vừa xóa: đóng form + refetch danh sách + toast, không retry tự động. <span class="wf-callout">10</span></span></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">10</span><span><b>Mọi lỗi hiển thị copy NGUYÊN VĂN bảng docs/06 §5</b>, kèm traceId rút gọn khi có; race 2 admin cùng sửa một dự án → PATCH sau vẫn 200 (last-write-wins theo contract hiện tại) nhưng audit giữ đủ diff hai lần — ghi chú để PM cân nhắc optimistic-lock về sau. <span class="ref">docs/06 §5</span> <span class="ref">BR-ADM-02</span></span></li></ol></div><h2 id="_5-empty-loading-error-responsive" tabindex="-1">5. Empty / Loading / Error + responsive <a class="header-anchor" href="#_5-empty-loading-error-responsive" aria-label="Permalink to &quot;5. Empty / Loading / Error + responsive&quot;">​</a></h2><div class="wf"><div class="wf-grid cols-3"><div class="wf-col"><span class="wf-state-label">EMPTY — CHƯA CÓ DỰ ÁN NÀO</span><div class="wf-card"><div class="pad"><div class="wf-empty"><span class="icon">🏗</span><div class="wf-title">Chưa có dự án nào</div><div class="wf-text" style="margin-top:6px;">Danh mục dự án NOXH là đầu vào bắt buộc của tin đăng (SC-42) và trang mua nhà (SC-02/04) — tạo dự án đầu tiên hoặc seed dữ liệu mẫu (chỉ dev).</div><div class="wf-col" style="gap:6px;margin-top:12px;"><span class="wf-btn primary block">＋ Tạo dự án đầu tiên</span><span class="wf-btn ghost block">Seed mẫu: `npm run db:seed:projects` <span class="wf-callout">11</span></span></div></div></div></div></div><div class="wf-col"><span class="wf-state-label">LOADING — SKELETON</span><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><div class="wf-skeleton" style="height:32px;"></div><div class="wf-skeleton" style="height:52px;"></div><div class="wf-skeleton" style="height:52px;"></div><span class="wf-small">Topbar + filter hiện ngay; thân bảng skeleton; đổi filter không flash empty (giữ khung — docs/05 §1.4).</span></div></div></div><div class="wf-col"><span class="wf-state-label">ERROR — KHÔNG LOAD ĐƯỢC DANH SÁCH</span><div class="wf-card"><div class="pad"><div class="wf-error-box"><div class="wf-title">Không tải được danh sách dự án</div><div class="wf-text" style="margin-top:6px;">Kiểm tra kết nối và thử lại. Lỗi tiếp diễn → báo dev kèm mã trace.</div><div class="wf-trace" style="margin-top:8px;">traceId: 7c2f…9ab4</div><span class="wf-btn" style="margin-top:10px;">Thử lại</span></div></div></div></div></div><div class="wf-note" style="max-width:760px;margin-top:12px;"><b>Responsive</b> (admin desktop-first — không vẽ khung mobile riêng): ≥ 1280px rail 200px + đủ 9 cột; 768–1279px gộp Địa chỉ vào khối tên dự án, ẩn cột Tổng căn + Cập nhật; dưới 768px bảng cuộn ngang với cột hành động sticky phải, form chuyển 1 cột, nút Xóa/Tạo dính đáy. Rail thu thành icon-only.</div></div><div class="wf-legend"><div class="t">Chú thích trạng thái</div><ol><li><span class="num">11</span><span><b>Đủ 4 trạng thái</b> Loading → Empty → Error (+traceId) → Data cho khung bảng; form có trạng thái riêng (pristine/dirty/submitting/error-per-field). Seed CLI `npm run db:seed:projects` là tiện ích dev (FR-ADM-05) — nút trong empty state chỉ hiện khi env không phải production. Icon 🏗 là placeholder vị trí — production dùng icon set thật (docs/05 §7). <span class="ref">FR-ADM-05</span> <span class="ref">docs/05 §1.4</span></span></li></ol></div><h2 id="_6-checklist-designer-khi-dung-figma-cho-sc-43" tabindex="-1">6. Checklist designer khi dựng Figma cho SC-43 <a class="header-anchor" href="#_6-checklist-designer-khi-dung-figma-cho-sc-43" aria-label="Permalink to &quot;6. Checklist designer khi dựng Figma cho SC-43&quot;">​</a></h2><ul><li>[ ] Đủ layout: bảng desktop 9 cột / thu gọn 1024 / cuộn ngang 768 (sticky cột hành động) — không cần khung mobile riêng (admin desktop-first)</li><li>[ ] Cột + field &quot;Trần bán lại/m²&quot; nhấn mạnh thị giác (khối đỏ ở form, in đậm ở bảng) kèm giải thích BR-HS-06 tại chỗ — designer KHÔNG được làm mờ mức nhấn này</li><li>[ ] Form đủ 20 nhóm trường theo docs/06 §4.10, hiển thị constraint từng field (min/max/độ dài) + unitTypes dạng bảng con (≤30 dòng) + amenities dạng chip (≤50)</li><li>[ ] Trạng thái form: pristine (Save disabled) · dirty (highlight trường đổi) · submitting (nút loading) · error-per-field (400 errors[]) · 409 highlight Tên + Địa chỉ</li><li>[ ] Delete-confirm: danger modal, reason 10–500, type-to-confirm mã dự án, cảnh báo tin tham chiếu + ghi chú gap docs/08 cho PM</li><li>[ ] Toast: 201 create · 200 update partial (nêu số trường đổi) · 409/404/400 copy nguyên văn docs/06 §5 · mọi mutation kèm chữ &quot;audit … đã ghi&quot;</li><li>[ ] Empty state có CTA tạo mới + seed CLI (chỉ dev) · Error box + traceId</li><li>[ ] Không emoji icon trong UI production (🏗/＋/✕/⭳ trong wireframe chỉ là placeholder vị trí)</li><li>[ ] Không vẽ: ảnh dự án, GPS/bản đồ, milestone %, lịch thanh toán — ngoài contract docs/06 §4.10</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ cần PM duyệt trên docs/08 trước.</p></div>',21)])])}const f=a(i,[["render",d]]);export{g as __pageData,f as default};
